import Headimg2 from '../../../assests/images/catpic.jpg'
import Center from "./Center"
import Cards from "./Cards"
import '../../../styles/container.css';

//function 
const Ypage2 = ()=>{
    return (
        <div>
            <Headimg  logo = {Headimg2}  title = "Donate" dec = "Way to Give"/>
            <Center />
            <div className = "card-container">
            <Cards />
            <Cards />
            </div>
            
        </div>
    )
}

//export
export default Ypage2
